const LOGIN_USER_KEY = 'flood-login-user-v1'
/** 登录接口返回的用户信息（字段与登录响应 data 对齐，按需取用） */
export interface LoginUserInfo {
  userId?: string
  userName?: string
  nickName?: string
  phone?: string
  avatar?: string
  tokenType?: string
  roles?: Array<{ roleName?: string; roleKey?: string }>
  roleKeys?: string[]
  [key: string]: unknown
}
export function setLoginUser(user: LoginUserInfo | undefined | null) {
  try {
    if (user && typeof user === 'object') uni.setStorageSync(LOGIN_USER_KEY, JSON.stringify(user))
    else uni.removeStorageSync(LOGIN_USER_KEY)
  } catch { /* ignore */ }
}
export function getLoginUser(): LoginUserInfo | undefined {
  try {
    const raw = uni.getStorageSync(LOGIN_USER_KEY)
    if (!raw) return undefined
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw
    return parsed && typeof parsed === 'object' ? (parsed as LoginUserInfo) : undefined
  } catch { return undefined }
}
export function clearLoginUser() { try { uni.removeStorageSync(LOGIN_USER_KEY) } catch { /* ignore */ } }

