[{"type":"text","text":"// 登录密码加密：AES-256-CBC + PKCS7，输出 base64。
// 与后端 com.zhishu.common.core.utils.AESUtil 对齐（AES/CBC/PKCS5Padding，16 字节块下 PKCS5 与 PKCS7 等价）：
//   key = 'A-16-Byte-keyValA-16-Byte-keyVal' (32字节 => AES-256)
//   iv  = 'A-16-Byte-String' (16字节)
// 基于 crypto-js（纯 JS，兼容 H5/微信小程序）。替换原手写 AES 实现：
// 其 initTables 循环自 2 起跳导致 SBOX[1] 缺项，密文与后端不一致（见 .plan/bug-login-aes-mismatch-20261117.md）。
import CryptoJS from 'crypto-js'

const DEFAULT_KEY = 'A-16-Byte-keyValA-16-Byte-keyVal'
const DEFAULT_IV = 'A-16-Byte-String'

function aesOptions(key: string, iv: string) {
  return {
    iv: CryptoJS.enc.Utf8.parse(iv),
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7,
  }
}

export function aesEncrypt(plain: string, key = DEFAULT_KEY, iv = DEFAULT_IV): string {
  const encrypted = CryptoJS.AES.encrypt(CryptoJS.enc.Utf8.parse(plain), CryptoJS.enc.Utf8.parse(key), aesOptions(key, iv))
  return encrypted.ciphertext.toString(CryptoJS.enc.Base64)
}

export function aesDecrypt(cipherB64: string, key = DEFAULT_KEY, iv = DEFAULT_IV): string {
  const cipherParams = CryptoJS.lib.CipherParams.create({ ciphertext: CryptoJS.enc.Base64.parse(cipherB64) })
  const decrypted = CryptoJS.AES.decrypt(cipherParams, CryptoJS.enc.Utf8.parse(key), aesOptions(key, iv))
  return decrypted.toString(CryptoJS.enc.Utf8)
}
"}]

